/// <summary>
/// PaffH 04.08.22
/// save data transfer error messages 
/// to table NDXDataTransferError
/// </summary>
class NDXDataTransferErrorClass
{
    private NDXDataTransferError nDXDataTransferError;
    private NDXCounterErrorMessages counterErrorMessages;
    private RefTableId refTableId;


}

Method.Source:
/// <summary>
/// PaffH 04.08.22
/// </summary>
/// <param name = "_refTableId">RefTableId</param>
/// <returns>NDXDataTransferErrorClass</returns>
public static NDXDataTransferErrorClass construct(RefTableId _refTableId)
{
    NDXDataTransferErrorClass nDXDataTransferErrorClass = new NDXDataTransferErrorClass();
    nDXDataTransferErrorClass.refTableId = _refTableId;
    return nDXDataTransferErrorClass;
}

/// <summary>
/// PaffH 04.08.22
/// delete existing log entries
/// </summary>
public void deleteExistingLog()
{
    delete_from nDXDataTransferError 
        where nDXDataTransferError.RefTableId == refTableId;
}

/// <summary>
/// PaffH 04.08.22
/// start new error log for a record
/// </summary>
/// <param name = "_refRecId">RefRecId</param>
public void startNewError(RefRecId _refRecId)
{
    if (nDXDataTransferError)
    {
        this.endError();
    }
    nDXDataTransferError = NDXDataTransferError::Create(refTableId, _refRecId, true);
}

/// <summary>
/// PaffH 04.08.22
/// all error messages for 1 record are saved
/// </summary>
public void endError()
{
    if (!nDXDataTransferError)
    {
        return;
    }
    nDXDataTransferError.selectForUpdate(true);
    nDXDataTransferError.CounterErrorMessages = counterErrorMessages;
    ttsbegin;
    nDXDataTransferError.write();
    ttscommit;
    nDXDataTransferError = null;
    counterErrorMessages = 0;
}

/// <summary>
/// PaffH 04.08.22
/// add new error message
/// </summary>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_errorMessageClass">NDXErrorMessageClass</param>
/// <param name = "_endError">boolean</param>
public void addError(RefRecId _refRecId, NDXErrorMessageClass _errorMessageClass, boolean _endError = true)
{
    if (_refRecId != nDXDataTransferError.RefRecId)
    {
        nDXDataTransferError = NDXDataTransferError::find(refTableId, _refRecId);
        counterErrorMessages = nDXDataTransferError.CounterErrorMessages;
    }

    if (!nDXDataTransferError)
    {
        this.startNewError(_refRecId);
    }
    NDXDataTransferErrorLine::addErrorMessageClass(nDXDataTransferError.RecId, _errorMessageClass);
    ++counterErrorMessages;
    if (_endError && _refRecId != nDXDataTransferError.RefRecId)
    {
        this.endError();
    }
}
